-- UPDATE public.courses SET title = 'Cybersecurity Fundamentals', description = 'Learn network security, ethical hacking, and threat prevention.' WHERE id = 'cybersecurity' AND description IS NOT DISTINCT FROM 'By the end, you will describe common threats, apply basic access and data safeguards, review a small application scenario, and present a safe assessment and remediation plan. No security tools or offensive experience are required. Plan for about 8 hours. Activities stay defensive and use fictional examples; no real-target testing is needed.';
-- UPDATE public.modules SET course_id = 'cybersecurity', title = 'Security Operations and Incident Response', description = 'Detecting, responding to, and recovering from security incidents' WHERE id = '79625752-2530-43f5-b19d-3416a1d43625' AND description IS NOT DISTINCT FROM 'Prepare for incidents, preserve evidence carefully, communicate clearly, and improve controls after recovery.';
-- UPDATE public.modules SET course_id = 'cybersecurity', title = 'Web and Application Security', description = 'Securing web applications and APIs' WHERE id = '8ecfd9db-09a7-48fb-85a9-5304dd8c2d37' AND description IS NOT DISTINCT FROM 'Recognize common application weaknesses and select secure design and verification practices.';
-- UPDATE public.modules SET course_id = 'cybersecurity', title = 'Ethical Hacking and Penetration Testing', description = 'Offensive security techniques for defense' WHERE id = '39b87d40-45e1-457b-a499-d3a1d01f9fc5' AND description IS NOT DISTINCT FROM 'Understand authorized assessment as a governed process focused on scope, evidence, remediation, and retesting.';
-- UPDATE public.modules SET course_id = 'cybersecurity', title = 'Cybersecurity Foundations', description = 'Core concepts and terminology in cybersecurity' WHERE id = '52596831-914b-4353-9666-fe4aa895b2fc' AND description IS NOT DISTINCT FROM 'Protect information by understanding its value, likely threats, and the confidentiality, integrity, and availability goals.';
-- UPDATE public.lessons SET module_id = '79625752-2530-43f5-b19d-3416a1d43625', title = 'Security Awareness and Training', content = 'Regular training to help employees recognize and avoid security threats.' WHERE id = 'bebb003b-dd29-49cb-9aa8-226951647a6a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Design security guidance that helps people recognize, report, and recover from common mistakes without blame, and communicate a defensive assessment.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A new employee clicks a convincing delivery message and immediately hides the mistake because they fear punishment.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does a blame-focused culture make incidents safer or harder to contain?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Training should use realistic examples, accessible formats, clear reporting paths, and repeated practice. Encourage prompt reporting so responders can limit impact.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Teach staff to verify unexpected payment changes through a known contact and report suspicious messages using a visible channel. Explain what happens after a report.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Security Assessment &amp; Remediation Lab: use only the supplied fictional scenario; state the authorized scope, asset, threat, likely weakness, impact, defensive mitigation, and safe retest. Present evidence without real personal data or exploit steps, plus one limit and follow-up control.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>People are part of the defense when systems make safe actions easy and reporting safe. Project evidence is not submitted to or persisted by this platform.</p></section>';
-- UPDATE public.lessons SET module_id = '79625752-2530-43f5-b19d-3416a1d43625', title = 'Security Policies and Procedures', content = 'Documents that outline an organization''s approach to managing security.' WHERE id = '867fce75-3b18-40ec-9f99-794ee151dcbd' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Connect a written security policy to clear roles, practical procedures, and review dates.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A company policy says “use strong passwords,” but staff do not know how to report a suspected compromise.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What observable action should the policy enable?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A policy states expectations and ownership; a procedure explains repeatable steps. Guidance should be understandable, accessible, proportional to risk, and reviewed when systems change.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A compromised-account procedure can name the reporting channel, immediate account protection steps, evidence to preserve, and the responder responsible for follow-up.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Rewrite “be careful online” as one actionable rule with an owner and a reporting path.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A policy protects people when they can find and follow it.</p></section>';
-- UPDATE public.lessons SET module_id = '79625752-2530-43f5-b19d-3416a1d43625', title = 'Digital Forensics Basics', content = 'Application of investigation and analysis techniques to gather and preserve evidence.' WHERE id = '0c8d03a1-936a-4842-85df-d7fde79b7c88' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain evidence preservation, chain of custody, and the value of minimizing changes during an investigation.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A staff member finds a suspicious file and opens it repeatedly to see what happens, changing timestamps and possibly triggering behavior.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>How can the team preserve what it observed without further altering the device?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Forensic practice records who handled evidence, when, and what was done. Follow approved procedures, preserve original data, use qualified responders, and protect private information.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Record device identifier, observer, time, and visible state; isolate according to policy and contact the response lead instead of experimenting on the original.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>List the first documentation steps for a fictional company laptop. Why should an untrained responder avoid exploring the suspicious file?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Evidence is most useful when its origin and handling are trustworthy.</p></section>';
-- UPDATE public.lessons SET module_id = '79625752-2530-43f5-b19d-3416a1d43625', title = 'Incident Response Lifecycle', content = 'Structured approach to handling security breaches and cyber attacks.' WHERE id = '3ce40e11-4386-40fa-87a3-2e36894dc8f4' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe preparation, detection, containment, recovery, and learning as coordinated response activities.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A nonprofit suspects an account was used to download a donor list, but staff are unsure who should disable access or notify leadership.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What first actions limit harm while keeping evidence and communication organized?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Incident response prepares roles and contacts, detects and assesses, contains impact, removes the cause, restores service, and reviews lessons. Legal, privacy, and notification decisions should follow organizational policy and qualified advice.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A tabletop exercise can rehearse who freezes a compromised account, preserves logs, contacts the incident lead, and documents decisions.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Arrange response actions for a fictional exposed account. Identify one action that could destroy evidence if done carelessly.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Preparation makes a stressful response more deliberate and coordinated.</p></section>';
-- UPDATE public.lessons SET module_id = '79625752-2530-43f5-b19d-3416a1d43625', title = 'Security Monitoring and SIEM', content = 'Real-time analysis of security alerts generated by applications and network hardware.' WHERE id = '6fe6b15d-c314-4b19-9a2a-4c06c1c01671' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe how security logs support detection while preserving privacy and making alerts actionable.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A service records repeated failed logins, but no one reviews the logs or knows who receives a high-risk alert.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What event matters, what context is needed, and who responds?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A SIEM collects and correlates selected security events. Logs should use consistent timestamps, restricted access, appropriate retention, and avoid storing passwords or unnecessary sensitive content.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Alert on unusual failure rates with account and source context, then route to a named responder with an investigation playbook.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Design one alert for repeated sign-in failures. State its threshold rationale, responder, privacy limit, and false-positive review.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Monitoring works when signals lead to a safe, owned response.</p></section>';
-- UPDATE public.lessons SET module_id = '8ecfd9db-09a7-48fb-85a9-5304dd8c2d37', title = 'Application and System Hardening', content = 'Removing unnecessary software, changing default passwords, and disabling unused services.' WHERE id = '6027562f-5ee5-43c2-91ef-e696fdbd1d8f' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Reduce unnecessary exposure through updates, secure defaults, limited services, and reviewed configuration.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A prototype server still has its default admin password and an unused management service exposed to the internet.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which exposure can be removed before the service is used by customers?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Hardening reduces attack surface: remove unnecessary services, change defaults, apply supported updates, limit permissions, and review configuration. Record changes so they can be maintained.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Disable the unused service, restrict management access to an approved private path, rotate default credentials, and verify the service remains functional.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Create a five-item hardening checklist for a fictional web server. Include a way to confirm each change.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A secure baseline is maintained through repeatable checks and updates.</p></section>';
-- UPDATE public.lessons SET module_id = '8ecfd9db-09a7-48fb-85a9-5304dd8c2d37', title = 'Web Application Firewalls (WAF)', content = 'Appliances, server plugins, or filters that apply a set of rules to HTTP conversations.' WHERE id = '942f4bed-d1f9-4374-97eb-384e018f70f5' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain a WAF as one filtering layer and identify what application controls it cannot replace.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A team enables a web firewall and assumes its application no longer needs input checks or access control.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What happens when an allowed request is still unauthorized?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A WAF can inspect and filter some web traffic patterns, helping reduce exposure to known classes of requests. Rules can miss attacks or block valid users; application logic remains responsible for authorization and safe data handling.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use a WAF as defense in depth, monitor false positives, and still parameterize queries and enforce access within the application.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>A request passes a WAF but asks for another user’s private record. Which control must still decide whether to return it?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Filtering at the edge complements secure application design; it does not substitute for it.</p></section>';
-- UPDATE public.lessons SET module_id = '8ecfd9db-09a7-48fb-85a9-5304dd8c2d37', title = 'API Security Fundamentals', content = 'Authentication, authorization, input validation, and rate limiting for APIs.' WHERE id = '3ab4a821-d820-412b-bd78-99d757625d6a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Distinguish authentication from authorization and apply validation and rate controls to an API scenario.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A user is signed in but changes `/orders/123` to `/orders/124` and sees another person’s order.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does a valid login prove permission to every record?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Authentication establishes an identity; authorization checks whether that identity may perform the requested action on the specific resource. Validate input, limit abusive traffic, and log safely.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For an order request, check the authenticated user’s ownership or role on the server for every read and update. Do not rely on a hidden button in the interface.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Classify a signed-in user’s unauthorized record access. Name where the authorization check belongs and one safe test case.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Every request needs permission checks for the resource it touches.</p></section>';
-- UPDATE public.lessons SET module_id = '8ecfd9db-09a7-48fb-85a9-5304dd8c2d37', title = 'Secure Coding Practices', content = 'Input validation, output encoding, proper error handling, and using security frameworks.' WHERE id = '431cb045-9fe8-4d9a-8d35-baf1f258e818' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Apply input validation, output encoding, least privilege, and safe error handling in a code review.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A feedback form prints submitted text directly into an administrative page, where a script-like value could be interpreted as markup.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Should user text be treated as trusted code?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Validate data against expected formats, encode output for its context, use parameterized database queries, minimize privileges, and avoid exposing sensitive internals in errors.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Render feedback as text using a safe templating mechanism and ensure a database lookup binds user values as parameters.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Review a fictional form flow and list one validation rule, one output-safety control, and one logging detail to avoid.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Secure coding treats external input as untrusted and limits what a failure can expose.</p></section>';
-- UPDATE public.lessons SET module_id = '8ecfd9db-09a7-48fb-85a9-5304dd8c2d37', title = 'Common Web Vulnerabilities', content = 'Injection, broken authentication, sensitive data exposure, XML external entities, and broken access control.' WHERE id = '3632bc4d-f2e7-47a1-8aa2-dc5c679b2a9d' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Recognize broad web risk patterns and pair each with a defensive design practice.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A booking site trusts a hidden form field to decide which customer’s appointment to display.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can a user change a browser field, and where must authorization be checked?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Injection, broken access control, insecure authentication, and unsafe data handling are common risk categories. Validate at boundaries, use parameterized queries, encode output, and enforce access on the server.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For each booking request, derive the permitted record from the authenticated user on the server instead of trusting a submitted account ID.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Review a fictional design that trusts a client-supplied role. State the risk category and a server-side mitigation.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Security controls must be enforced at the boundary that can actually protect the data.</p></section>';
-- UPDATE public.lessons SET module_id = '39b87d40-45e1-457b-a499-d3a1d01f9fc5', title = 'Post-Exploitation and Reporting', content = 'Steps taken after successfully breaking into a system and how to report discoveries.' WHERE id = '9b0af0d0-06c7-4e0a-8a36-5c9fcc68e76d' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Turn an authorized finding into a concise report with impact, evidence, remediation, and retest criteria.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A security reviewer tells the engineering team “the app is vulnerable” without explaining which workflow or user is affected.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can the team prioritize or fix a claim without reproducible, safe evidence?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A useful report includes scope, summary, affected asset, severity rationale, minimal evidence, impact, remediation, and verification steps. Do not retain secrets or unnecessary personal data.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Report “a standard user could view another synthetic test account’s profile; enforce ownership on the server and retest both owner and non-owner access.”</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Write a fictional finding summary, impact, recommended fix, and one measurable retest condition.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Clear reporting helps defenders repair the risk and confirm that the fix works.</p></section>';
-- UPDATE public.lessons SET module_id = '39b87d40-45e1-457b-a499-d3a1d01f9fc5', title = 'Exploitation Techniques', content = 'Using tools like Metasploit to exploit security weaknesses in systems and applications.' WHERE id = '226c2dec-3aa4-45d4-86ad-1da29b2c8391' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Recognize exploit risk conceptually and prioritize safe remediation without operational instructions.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A review finds that a test application accepts malformed input and may expose a record belonging to another test account.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What evidence can confirm the risk safely without accessing real people’s data?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>An exploit uses a weakness to violate a system’s expected behavior. Assessments should use isolated test data, least-impact proof, explicit authorization, and clear stop rules.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>In a local training app, use provided test accounts to demonstrate whether a role boundary is enforced; record only the synthetic record IDs and expected-versus-actual behavior.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>For a fictional input-validation finding, describe the risk and a safe verification approach. Avoid payloads, live targets, or instructions for extracting data.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Demonstrate the smallest safe proof, then focus on fixing and retesting the control.</p></section>';
-- UPDATE public.lessons SET module_id = '39b87d40-45e1-457b-a499-d3a1d01f9fc5', title = 'Scanning and Enumeration', content = 'Using tools like Nmap to discover network information and vulnerabilities.' WHERE id = 'd67b3062-aa4b-43ab-9792-abcf4513835d' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain at a high level what an authorized inventory scan can reveal and how to avoid disruption.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A school’s IT team wants to identify outdated devices on its internal test network before a planned maintenance window.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What controls prevent an inventory check from interrupting classes or collecting excess data?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>An authorized scan can identify reachable assets and apparent service versions. Results may be incomplete or wrong; scanning speed and timing can affect service stability.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use a pre-approved inventory tool against a documented lab range, limit the schedule and rate, notify owners, and verify findings manually before remediation.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Create a safe scan plan for a fictional lab: owner, exact range, time window, rate limit, stop condition, and result-retention rule.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Discovery must be authorized, proportionate, and coordinated with service owners.</p></section>';
-- UPDATE public.lessons SET module_id = '39b87d40-45e1-457b-a499-d3a1d01f9fc5', title = 'Reconnaissance and Information Gathering', content = 'Collecting information about a target before attempting to exploit vulnerabilities.' WHERE id = '96250380-cc77-4ac1-9c8d-06d4d14b0b09' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Understand why an authorized assessment begins with scope and asset inventory, without collecting unrelated personal data.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A company commissions a review of its staging service, but the asset list includes an old domain now owned by another organization.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What would make continued testing unsafe?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Defensive asset discovery identifies systems the organization owns and intended review boundaries. Keep collection proportionate, document sources, and exclude third-party or personal data unless expressly authorized.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use an approved internal inventory and owner confirmation to identify the staging hostname, contact, time window, and permitted test accounts.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Given a fictional assessment request, list four scope questions and one condition that requires stopping to seek approval.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Stay within verified scope and minimize information collected.</p></section>';
-- UPDATE public.lessons SET module_id = '39b87d40-45e1-457b-a499-d3a1d01f9fc5', title = 'What is Ethical Hacking?', content = 'Authorized attempt to gain unauthorized access to a computer system, application, or data.' WHERE id = '6665b617-ebe9-48e4-aa1e-2e185c8d4ace' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe the authorization, scope, safety, and reporting requirements of a legitimate security assessment.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A student notices a flaw on a public website and wants to “prove it” by testing real accounts.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does curiosity provide permission, and who could be affected by the test?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A security assessment requires written authorization, defined systems and methods, time limits, data-handling rules, emergency contacts, and a safe reporting path. Without authorization, do not probe.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use a deliberately vulnerable training lab or a written tabletop scenario. Agree on scope before collecting any evidence and stop if activity may affect real users.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Review a fictional scope that lists one test lab but omits its API subdomain. Is the omitted target in scope? What clarification is needed?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Permission and boundaries are part of security work, not administrative extras.</p></section>';
-- UPDATE public.lessons SET module_id = '52596831-914b-4353-9666-fe4aa895b2fc', title = 'Cryptography Fundamentals', content = 'Study of techniques for secure communication in the presence of third parties.' WHERE id = '3144f424-b48c-48b6-b1f7-cdc4a67d9b62' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Distinguish encryption, hashing, and digital signatures by the security property each supports.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>An application needs to store passwords, send private account data, and verify that a software release came from its publisher.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Should it use one cryptographic operation for all three jobs?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Encryption is reversible with the right key; password hashing is intentionally costly to verify guesses; digital signatures help verify origin and integrity. Use reviewed libraries and established protocols.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use a dedicated password-hashing function for passwords, TLS for network traffic, and a signed release process for software provenance.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Match private message, password verifier, and signed update to a cryptographic purpose. Name one mistake caused by inventing a custom cipher.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Choose established cryptography for a specific purpose and keep keys protected.</p></section>';
-- UPDATE public.lessons SET module_id = '52596831-914b-4353-9666-fe4aa895b2fc', title = 'Network Security Basics', content = 'Firewalls, intrusion detection/prevention systems, and virtual private networks.' WHERE id = 'e53dea87-9c2e-4e27-afaf-69e9e2512128' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how segmentation, firewalls, and secure transport reduce exposure without guaranteeing safety.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A guest Wi-Fi network can currently reach the office printer and file server.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which systems need to communicate, and which paths can be closed?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Networks connect devices through routes and ports. Firewalls allow or deny traffic by policy; segmentation separates systems; TLS protects data in transit when configured and validated properly.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Allow guest devices to reach the internet while denying access to internal management services. Review logs and test the intended user flows after changing a rule.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Draw a small office network with guest, staff, and server segments. Mark one justified allowed path and one blocked path.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A network boundary is useful when its rules match real needs and are reviewed.</p></section>';
-- UPDATE public.lessons SET module_id = '52596831-914b-4353-9666-fe4aa895b2fc', title = 'Types of Cyber Threats', content = 'Understanding different attack methods and their characteristics.' WHERE id = '6bc7c032-37dc-4af8-8624-68525371d797' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Recognize common threat categories and connect each to a practical defensive control.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>An employee receives a convincing message asking them to open an invoice and enter a password on a lookalike page.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What clues could help them pause, and what organizational control limits the impact?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Phishing deceives people into unsafe actions; malware runs unwanted code; ransomware can disrupt access; credential theft misuses account secrets. Threat likelihood and impact depend on context.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use phishing-resistant authentication where possible, verify unusual requests through a known channel, keep devices patched, and maintain tested backups.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>For a fictional invoice email, identify a warning sign, a safe reporting action, and one control that limits damage if someone clicks.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Build layered defenses so one mistake does not become a major incident.</p></section>';
-- UPDATE public.lessons SET module_id = '52596831-914b-4353-9666-fe4aa895b2fc', title = 'The CIA Triad', content = 'Foundational model for developing security policies to protect organizations.' WHERE id = '03d79f62-a0b7-4b00-9e9d-f261b603fd05' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use confidentiality, integrity, and availability to describe different security goals.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A clinic’s appointment service is temporarily offline, while a separate report contains altered visit dates.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Are these the same kind of security failure?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Confidentiality limits access to authorized people; integrity protects correctness and completeness; availability keeps systems usable when needed. A control may help one goal while creating a tradeoff for another.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Encryption can protect confidentiality of stored data, audit logs can help detect integrity changes, and tested backups support availability.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Classify accidental public disclosure, changed records, and an unavailable service under the affected goals. Which could affect more than one?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Security decisions become clearer when teams name the property they are protecting.</p></section>';
-- UPDATE public.lessons SET module_id = '52596831-914b-4353-9666-fe4aa895b2fc', title = 'What is Cybersecurity?', content = 'Cybersecurity is the practice of protecting systems, networks, and programs from digital attacks.' WHERE id = '5696983e-7126-4e93-a4e2-db8702148dce' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain cybersecurity as the practice of reducing harm to systems, data, and people.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A small nonprofit stores donor contact details in a shared drive. A volunteer accidentally shares the folder publicly.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What needs protecting, who should have access, and what harm could disclosure cause?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Cybersecurity combines people, processes, and technology to protect confidentiality, integrity, and availability. It manages risk; it cannot promise that incidents will never happen.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Start with an inventory of donor data, its purpose, approved readers, retention period, and a process for reporting accidental exposure.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Name one digital asset, one plausible threat, and one safeguard that fits a small organization’s resources.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Security begins by understanding what matters and how it could be harmed.</p></section>';
-- UPDATE public.courses SET title = 'UI/UX Design Principles', description = 'User research, wireframing, prototyping, and user testing methodologies.' WHERE id = 'ui_ux' AND description IS NOT DISTINCT FROM 'By the end, you will investigate a user need, map a journey, sketch and test an interface, and present a case study grounded in evidence. No design software is required. Plan for about 7 hours. You will produce an end-to-end redesign case study with research notes, prototype decisions, and usability findings.';
-- UPDATE public.modules SET course_id = 'ui_ux', title = 'Design Thinking and Prototyping', description = 'Human-centered approach to innovation' WHERE id = '9defed1f-d690-4845-a615-340d2415e355' AND description IS NOT DISTINCT FROM 'Iterate through testing, accessibility, handoff, and evidence-based project presentation.';
-- UPDATE public.modules SET course_id = 'ui_ux', title = 'User Interface Design', description = 'Creating visually appealing and functional interfaces' WHERE id = '7b5295fa-7112-4174-99e5-86ffdc797140' AND description IS NOT DISTINCT FROM 'Turn structure into a readable visual hierarchy and test a low-fidelity prototype before polishing it.';
-- UPDATE public.modules SET course_id = 'ui_ux', title = 'User Experience Foundations', description = 'Core principles of user-centered design' WHERE id = '0ab93a5c-ba5d-4a28-b167-9d79c10a67ae' AND description IS NOT DISTINCT FROM 'Frame a real user goal, gather evidence ethically, and organize a product so people can find and complete a task.';
-- UPDATE public.lessons SET module_id = '9defed1f-d690-4845-a615-340d2415e355', title = 'Design Trends and Future Directions', content = 'Neumorphism, glassmorphism, dark mode, and designing for emerging technologies.' WHERE id = '38bc8cba-bf4a-406a-a63a-d1ae4cb8f312' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Evaluate a visual trend by user needs, accessibility, maintenance, and evidence instead of novelty, then present a redesign case study.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A product team wants translucent text panels over photography because the effect is popular in a showcase.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can every user still read and interact with the content in different themes and conditions?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Trends can inspire exploration, but visual effects introduce contrast, performance, and support costs. Evaluate them against the task, content, devices, and user testing.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Prototype the effect with real copy, varied photo backgrounds, keyboard focus, and light/dark themes. Keep a simpler fallback if readability is unreliable.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>End-to-end redesign project: document a real or fictional user problem, research evidence, journey, information structure, prototype, usability observations, changes, and access checks. Present who it serves, why each decision follows evidence, what testing did not cover, and the next iteration.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A design choice is current when it works for its users, not merely because it is fashionable. This platform does not store project submissions.</p></section>';
-- UPDATE public.lessons SET module_id = '9defed1f-d690-4845-a615-340d2415e355', title = 'Design Handoff and Collaboration', content = 'Bridging the gap between design and implementation through clear communication.' WHERE id = '4228bc33-9d15-4df8-be0c-b48ada14d790' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Communicate design intent, states, measurements, and open questions so implementation can preserve the user experience.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A developer receives a polished screenshot but cannot tell what happens when a search returns no results.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which behavior and content are missing from a static picture?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A useful handoff includes responsive behavior, component states, content rules, accessibility requirements, and known tradeoffs. Conversation between design and engineering can reveal constraints early.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Annotate default, focus, loading, empty, and error states. Name the source of spacing/type tokens rather than giving isolated pixel guesses.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Prepare a handoff note for a search page. Include its empty state, keyboard behavior, and one implementation question.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A handoff is shared reasoning, not a picture passed over a wall.</p></section>';
-- UPDATE public.lessons SET module_id = '9defed1f-d690-4845-a615-340d2415e355', title = 'Accessibility in Design (a11y)', content = 'Ensuring that everyone can use, understand, navigate, and interact with the UI.' WHERE id = 'e818d9a3-abf3-4263-950c-d8724b99f8fd' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Identify design barriers across contrast, keyboard access, focus, labels, and information conveyed by color.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A user zooms a checkout page and the fixed footer covers the final payment control.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Does the page reflow and keep the action reachable?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Accessibility means people with diverse sensory, motor, and cognitive needs can perceive and operate a product. Consider keyboard order, visible focus, contrast, text resizing, captions, and clear labels.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Test the prototype with keyboard only and at 200% zoom. Give errors in text and keep focused controls from being obscured by sticky elements.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Audit one screen for one keyboard issue, one text/contrast issue, and one non-text alternative. Suggest a specific design fix for each.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Accessibility checks belong throughout design and implementation, not only at the final review.</p></section>';
-- UPDATE public.lessons SET module_id = '9defed1f-d690-4845-a615-340d2415e355', title = 'Usability Testing and Evaluation', content = 'Evaluating a product or service by testing it with representative users.' WHERE id = '6139fda3-eccf-4086-8862-cdfd3f4ad107' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Run a neutral task test, observe behavior, and turn findings into prioritized design changes.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A participant says a form is “fine,” but hesitates for thirty seconds before finding the Submit button.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which is stronger evidence: a general opinion or the observed difficulty completing a task?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Usability testing asks representative users to attempt realistic tasks. Give neutral prompts, avoid teaching, record errors and hesitation, and separate observation from interpretation.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Task: “Find the renewal date for your membership.” Record completion, misclicks, and participant comments; do not tell them where to look.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Write a task prompt and three observations for a prototype. How will you avoid leading the participant?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A small test can reveal actionable friction without pretending to represent every user.</p></section>';
-- UPDATE public.lessons SET module_id = '9defed1f-d690-4845-a615-340d2415e355', title = 'Design Thinking Process', content = 'Human-centered approach to innovation that draws from the designer''s toolkit.' WHERE id = '15b4f887-8483-4e21-9349-fbfbcb0bbb5b' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Move from observed user evidence to a testable problem statement and prototype.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A campus team proposes an app to solve late library returns, but has not checked why books are late.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Is an app the real need, or only one proposed solution?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Design thinking commonly moves through empathize, define, ideate, prototype, and test. These are useful activities, not a rigid linear guarantee of innovation.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Evidence may show students are unsure of due dates. A clearer reminder and renewal flow could solve the problem without building a new app.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Write a “How might we” question from an observed need. Check that it names an outcome without prescribing the solution.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Stay close to the user problem while remaining open to simpler solutions.</p></section>';
-- UPDATE public.lessons SET module_id = '7b5295fa-7112-4174-99e5-86ffdc797140', title = 'Color Theory and Application', content = 'Psychological effects of color, color harmony, and creating accessible color palettes.' WHERE id = '0df6c2f0-c03c-401c-a607-b76809f47c9e' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use color to reinforce meaning while preserving contrast and non-color cues.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A calendar marks unavailable appointments in red and available times in green, which is difficult for some users to distinguish.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What second signal communicates availability?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Color choices shape emphasis and mood, but color alone must not communicate status. Check text and control contrast and consider color-vision differences and theme changes.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Pair color with labels or icons such as “Available” and “Full.” Test foreground/background pairs with a contrast checker and review focus indicators.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Design a status legend using color plus text or shape. How would it remain understandable in grayscale?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Color is one communication channel; pair it with text, shape, or position.</p></section>';
-- UPDATE public.lessons SET module_id = '7b5295fa-7112-4174-99e5-86ffdc797140', title = 'Typography in UI Design', content = 'Selection, spacing, and styling of type to enhance readability and accessibility.' WHERE id = 'b1c8a955-31e4-4dbb-8a1d-4f12447c8901' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Choose type size, line length, and hierarchy that support reading across screens and zoom levels.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A benefits page uses pale 12px text and long unbroken lines, so workers miss eligibility details.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Can readers scan the information at their chosen zoom?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Typography affects readability through size, line height, weight, spacing, and measure. Use hierarchy to show relationships and avoid relying on font weight alone to indicate meaning.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use a comfortable body size, generous line height, headings in a logical order, and a readable content width. Test at 200% zoom and with the actual wording.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Revise a dense paragraph and three headings into a scannable hierarchy. What information must remain visible at increased zoom?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Readable text is a usability requirement, not an aesthetic extra.</p></section>';
-- UPDATE public.lessons SET module_id = '7b5295fa-7112-4174-99e5-86ffdc797140', title = 'Design Systems and Style Guides', content = 'Collections of reusable components guided by clear standards.' WHERE id = 'ad5b516b-cf6b-4e0e-9b5f-5c44ffd9399d' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use shared design tokens and reusable components while allowing context-specific decisions.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A product’s buttons look slightly different across pages, and teams fix the same spacing defect in several places.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which choices should be shared and which need a page-level reason?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A design system can include tokens for color and spacing, component behavior, accessibility guidance, and examples. Reuse supports consistency but cannot replace user testing.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Define one primary button with normal, hover, focus, disabled, and loading states. Document contrast and minimum target requirements alongside its appearance.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose three interface decisions to make reusable. Name a situation where a shared component would need a justified variation.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Consistency improves quality when components preserve useful behavior and remain maintainable.</p></section>';
-- UPDATE public.lessons SET module_id = '7b5295fa-7112-4174-99e5-86ffdc797140', title = 'Wireframing and Prototyping', content = 'Wireframes are basic visual guides used to suggest the arrangement of elements.' WHERE id = 'c25e991a-b033-4f1a-95b6-706abdca8747' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Build a low-cost representation of a flow to test structure and assumptions before visual polish.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A team spends days polishing a checkout screen before discovering customers need delivery dates before choosing a payment method.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What is the cheapest version that could reveal the ordering problem?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A wireframe focuses on structure and content; a prototype links screens or interactions. Fidelity should match the question: paper may test flow, while a coded prototype may test timing or responsive behavior.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Sketch three checkout screens and ask someone to find the earliest delivery date. Observe without coaching and note where the flow differs from your assumption.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Create a five-minute paper prototype for a course search. Write one task and one observation you want to learn.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Prototype to learn before investing in visual detail.</p></section>';
-- UPDATE public.lessons SET module_id = '7b5295fa-7112-4174-99e5-86ffdc797140', title = 'UI Design Fundamentals', content = 'Typography, color theory, layout, and visual hierarchy in interface design.' WHERE id = 'f72737d2-74f9-4c12-b217-1232f566cc18' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use hierarchy, spacing, alignment, and contrast to make the next useful action easy to notice.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A donation page gives equal visual weight to its goal, privacy note, amount choices, and unrelated promotional banner.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What does a first-time donor need first?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Visual hierarchy uses size, position, contrast, and grouping to communicate order. Consistent spacing and alignment reduce scanning effort; decorative emphasis should not undermine meaning.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Put the donation purpose and amount selection near the top, group related choices, and style the primary action distinctly while keeping privacy information easy to find.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Redesign the hierarchy of a page with a heading, explanation, three choices, and action. Explain which element should receive strongest emphasis and why.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A clear interface directs attention in service of the task.</p></section>';
-- UPDATE public.lessons SET module_id = '0ab93a5c-ba5d-4a28-b167-9d79c10a67ae', title = 'Interaction Design Principles', content = 'Creating meaningful relationships between people and the products they use.' WHERE id = 'fcdf0053-3fb8-4d72-bfec-1b7f9a5a60a8' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Design a control with clear state, feedback, and recovery for the action it performs.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A learner clicks “Save” on a long form and sees no change, so they click repeatedly and create duplicate requests.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What confirmation or pending state would build confidence?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Interaction design describes how a user acts and how the system responds. Controls need understandable affordances, visible state, timely feedback, and a way to recover from errors.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A Save button can disable during submission, show “Saving…,” then announce “Saved at 2:14 pm,” with an error message and retry if needed.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Sketch the states for a “Join waitlist” action: ready, pending, success, and failure. What does a keyboard or screen-reader user hear?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Every action should make its result and current state clear.</p></section>';
-- UPDATE public.lessons SET module_id = '0ab93a5c-ba5d-4a28-b167-9d79c10a67ae', title = 'Information Architecture', content = 'The structural design of shared information environments.' WHERE id = 'ae8b1666-a6fa-4c4f-8308-7d4ed4c4eac2' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Group and label content so users can predict where to find what they need.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A job seeker visits a career site for salary information but finds it buried under “Resources.”</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Would a person use the organization’s internal label or their own language?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Information architecture organizes content, navigation, and labels around user mental models. A sitemap shows hierarchy; card sorting can reveal how people group terms.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Group “salary range,” “benefits,” and “work location” under a job details area, then check whether users can locate them without hints.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Draft a five-item navigation for a learner looking for courses, progress, profile, and support. Ask what a new user might misunderstand.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A findable structure uses words and groupings the audience recognizes.</p></section>';
-- UPDATE public.lessons SET module_id = '0ab93a5c-ba5d-4a28-b167-9d79c10a67ae', title = 'User Research Methods', content = 'Interviews, surveys, usability testing, analytics, and contextual inquiry.' WHERE id = '12563d91-3880-4d54-a93d-6bc79ab717bf' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Select a research method that can answer a specific question while respecting participants and their data.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A library wants to understand why first-time visitors cannot find the room reservation policy.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Would asking users what they want answer where they get stuck?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Interviews explore motivations; observation reveals behavior in context; surveys can measure patterns across a larger group; usability sessions test a concrete task. Each method has limits and consent requirements.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Observe a volunteer completing a reservation task, ask neutral follow-up questions, and record where they hesitate without collecting unnecessary personal details.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose between interview, survey, and task observation for a question about navigation confusion. State the evidence and limitation each method provides.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Choose research by the uncertainty you need to reduce, not by habit.</p></section>';
-- UPDATE public.lessons SET module_id = '0ab93a5c-ba5d-4a28-b167-9d79c10a67ae', title = 'User-Centered Design Process', content = 'Understanding users, defining requirements, designing solutions, and evaluating outcomes.' WHERE id = '15425085-ebc8-40b5-be83-6c534d81123e' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Use an iterative cycle to connect observed needs, design choices, and test results.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A clinic redesigns a reminder screen based on an executive’s preference, but patients still miss appointments.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What evidence would reveal the patients’ actual barriers?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A user-centered cycle researches context, defines a focused problem, generates options, prototypes, tests, and revises. Teams revisit earlier steps when evidence changes the brief.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Instead of “make it modern,” define “help a patient confirm or reschedule in under one minute using a phone.” Test that task with representative participants.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Rewrite a vague feature request as a user goal and a way to observe whether the design helps.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Iteration is a learning method: each version should answer a question.</p></section>';
-- UPDATE public.lessons SET module_id = '0ab93a5c-ba5d-4a28-b167-9d79c10a67ae', title = 'What is UX Design?', content = 'User experience design is the process of creating products that provide meaningful and relevant experiences to users.' WHERE id = 'c3c68a1d-ba8f-4d4a-b217-031bf973798f' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe user experience as the result of a whole interaction, including its context and outcome.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A resident tries to book a public sports court, but the form rejects an address without explaining what needs to change.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Was the issue only color, or did the whole task fail?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>UX includes usefulness, clarity, accessibility, and the feelings created before, during, and after use. UI is the interface people interact with; it is one part of UX.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Map the resident’s path from finding a time to receiving confirmation. Include the form error and any information needed before booking.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Pick a familiar digital task and name its user, goal, one friction point, and evidence you would gather before redesigning it.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Good UX helps the intended person complete a meaningful task in their real context.</p></section>';
-- UPDATE public.courses SET title = 'DevOps & Cloud Basics', description = 'Learn Docker, Kubernetes, AWS basics, and CI/CD pipelines.' WHERE id = 'devops' AND description IS NOT DISTINCT FROM 'By the end, you will use basic command-line and Git workflows, explain how containers package an application, and plan a simple deployment with logs and health checks. Basic computer use is enough; no cloud account is required. Plan for about 8 hours. You will present a deploy-and-monitor plan for a small web service.';
-- UPDATE public.modules SET course_id = 'devops', title = 'Cloud Computing and AWS Basics', description = 'Understanding cloud platforms and services' WHERE id = '75d5fad0-7ce0-4b44-9883-e4088ac75d35' AND description IS NOT DISTINCT FROM 'Connect cloud resources, infrastructure definitions, CI/CD, and monitoring into a practical, cost-aware release plan.';
-- UPDATE public.modules SET course_id = 'devops', title = 'Containerization with Docker', description = 'Packaging and running applications in containers' WHERE id = 'cb995e82-7671-438f-9ead-8e88b3f75284' AND description IS NOT DISTINCT FROM 'Explain images, containers, orchestration, and basic container safeguards by following an application from build to run.';
-- UPDATE public.modules SET course_id = 'devops', title = 'Linux Foundations and Scripting', description = 'Core operating system skills for DevOps engineers' WHERE id = '5ba9d395-bdcf-4c98-aab4-08612f0a026e' AND description IS NOT DISTINCT FROM 'Use the terminal to inspect files, automate repeatable checks, and understand how a process communicates over a network.';
-- UPDATE public.lessons SET module_id = '75d5fad0-7ce0-4b44-9883-e4088ac75d35', title = 'CI/CD Pipelines and DevOps Practices', content = 'Continuous Integration and Continuous Delivery practices, tools like Jenkins, GitLab CI, and GitHub Actions.' WHERE id = '2e886a88-1780-46bd-9ab3-5d390811c8a5' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Map a code change through automated checks, artifact creation, release, and rollback, then present a small deployment plan.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A team discovers a broken production release after customers report an error; nobody knows which change introduced it.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What repeatable checks and release records could catch the issue earlier?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Continuous integration checks small changes regularly. Delivery pipelines build tested artifacts and deploy through controlled stages. Monitoring and rollback planning close the loop.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A pipeline can lint and test, build an image, scan it, deploy to staging, run a health check, and require approval before production.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Deploy-and-monitor project: use a sample service or paper plan; specify build, configuration, secret handling, test, deployment, health signal, owner, and rollback. Present the request flow, one failure drill, and the evidence that would show recovery.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A reliable release is observable and reversible, not merely automated. This course does not deploy or persist a learner’s project for them.</p></section>';
-- UPDATE public.lessons SET module_id = '75d5fad0-7ce0-4b44-9883-e4088ac75d35', title = 'Infrastructure as Code with Terraform', content = 'Writing configuration files to define and provide data center infrastructure using a high-level language.' WHERE id = '77c016fe-c7cd-4cae-9d54-7366428fab36' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how a declarative infrastructure plan previews repeatable changes before they are applied.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A team provisions a test environment manually and cannot remember which security group rule differs from production.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>How can the desired configuration be reviewed before resources change?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Infrastructure as Code records desired resources in versioned configuration. Terraform plans compare configuration with state and propose changes; reviewers must inspect destructive or broad changes before applying.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Keep reusable network and application settings in reviewed files, store state securely, and do not commit credentials or sensitive state into a public repository.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Review a hypothetical plan that replaces a database and opens a port to everyone. What questions must be answered before applying it?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A plan is a proposal, not proof of safety. Review scope, state, access, and recovery.</p></section>';
-- UPDATE public.lessons SET module_id = '75d5fad0-7ce0-4b44-9883-e4088ac75d35', title = 'Working with EC2 and S3', content = 'Elastic Compute Cloud for virtual servers and Simple Storage Service for scalable object storage.' WHERE id = '6641777a-240c-4cec-b1a8-4b81c75f0183' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Compare virtual compute and object storage by workload and apply access boundaries.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A product team stores images and runs a web process. One is a file-like object and the other executes code.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Should both be placed on a single server disk?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>EC2 provides configurable virtual compute. S3 stores objects in buckets. Access policies, encryption settings, lifecycle rules, and backups must match the data’s sensitivity and recovery needs.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A web service can store product images in a private bucket and return authorized URLs rather than exposing all objects publicly.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose EC2 or S3 for a process, an image archive, and a backup. State one control for preventing public access to sensitive objects.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Select each service by its role and protect the data with explicit access rules.</p></section>';
-- UPDATE public.lessons SET module_id = '75d5fad0-7ce0-4b44-9883-e4088ac75d35', title = 'Introduction to Amazon Web Services', content = 'Overview of AWS offerings including EC2, S3, RDS, Lambda, and networking services.' WHERE id = '7279fa81-2969-4905-9469-e1abb73fd39a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how a region, availability zone, identity policy, and service relate in a cloud design.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>An online shop wants its product site to remain available if one data center has an outage.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What geographic and failure boundaries should the design account for?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A region is a geographic area; availability zones are separated infrastructure locations within a region. IAM identities and policies govern who or what can act on services.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A design may place redundant application instances across zones and grant a deployment role only permission to update its intended service.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Label region, two zones, app instances, and a narrowly scoped deployment identity on a diagram. What can that identity not do?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Select cloud services to satisfy a requirement, and grant only the permissions the workflow needs.</p></section>';
-- UPDATE public.lessons SET module_id = '75d5fad0-7ce0-4b44-9883-e4088ac75d35', title = 'Cloud Computing Fundamentals', content = 'On-demand delivery of IT resources over the internet with pay-as-you-go pricing.' WHERE id = 'ee9ffb26-c5ee-46b9-91dc-803aa293a11f' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Choose between common cloud service models by identifying who operates each layer.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A small team wants to launch an API without owning physical servers, but still needs to manage its application and customer data.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which operational responsibilities move to the provider, and which remain with the team?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Infrastructure as a Service gives control over virtual machines; Platform as a Service manages more of the runtime; Software as a Service provides a finished application. Shared responsibility changes by service.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A managed application platform may reduce server maintenance while leaving application access, data retention, and secret configuration to the customer.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>For a hosted database and a virtual machine, list one provider responsibility and one customer responsibility for each.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Cloud services shift operational work; they do not remove ownership of data, access, and cost.</p></section>';
-- UPDATE public.lessons SET module_id = 'cb995e82-7671-438f-9ead-8e88b3f75284', title = 'Docker Security Best Practices', content = 'Image scanning, runtime security, resource limits, and proper user namespace configuration.' WHERE id = '95c6c057-73f8-441e-9104-65677c222ba3' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Identify container risks and choose least-privilege, patching, and secret-handling controls.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A demo container runs as root, mounts the host filesystem, and stores an API key in its image.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What could an attacker reach if the application were compromised?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Run with only necessary privileges, minimize mounts and capabilities, use trusted patched images, scan dependencies, and inject secrets through a managed runtime mechanism.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>For a read-only web service, run as a dedicated non-root user, expose only the needed port, and avoid mounting the Docker socket into the container.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Review a hypothetical service configuration for excessive privilege, broad mounts, and embedded secrets. Pair each issue with a safer control.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Isolation reduces risk but is not a substitute for least privilege, updates, and monitoring.</p></section>';
-- UPDATE public.lessons SET module_id = 'cb995e82-7671-438f-9ead-8e88b3f75284', title = 'Container Orchestration Basics', content = 'Introduction to Kubernetes concepts like pods, deployments, services, and namespaces.' WHERE id = 'f0c40145-d965-4e6b-94ad-fdb0bf369427' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe how an orchestrator maintains desired service instances and routes traffic to healthy containers.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A small service must restart after a process crash and run two copies during a planned busy period.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Who notices the failed process and decides how many copies should run?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>An orchestrator schedules containers, compares actual state with desired state, and can replace failed instances. Health checks inform decisions but need realistic thresholds.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A deployment can request two replicas and a readiness check. The service should receive traffic only after a replica is ready to serve it.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Sketch desired state, scheduler, two replicas, health checks, and traffic routing. What should happen during a rolling update if the new version fails its readiness check?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Orchestration automates operations; it does not guarantee an application is healthy or correctly configured.</p></section>';
-- UPDATE public.lessons SET module_id = 'cb995e82-7671-438f-9ead-8e88b3f75284', title = 'Working with Docker Images', content = 'Dockerfile instructions, building images, tagging, and using docker-compose for multi-container applications.' WHERE id = 'bbe4a136-b44e-40a9-b2a1-a925f0f7ea2b' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Create a smaller, traceable image and explain how its source and dependencies are controlled.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A service image includes a compiler, test files, and a development secret, making it large and unsafe to publish.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which files are needed at runtime? A build should include only what the running service requires.</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A reviewed Dockerfile and `.dockerignore` control build context. Pin trustworthy base images and dependencies, avoid secrets in layers, and rebuild to receive security updates.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A multi-stage build can compile in one stage and copy only the runtime output into the final stage. Scan the final artifact and keep a record of its digest.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Review a Dockerfile for broad copying, embedded keys, and unpinned dependencies. List the smallest safe corrections.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>An image is a release artifact; treat its contents and provenance as part of the supply chain.</p></section>';
-- UPDATE public.lessons SET module_id = 'cb995e82-7671-438f-9ead-8e88b3f75284', title = 'Docker Architecture and Components', content = 'Docker Engine, Docker Hub, images, containers, registries, and the client-server architecture.' WHERE id = '529f2f8c-a7ca-4b42-beb6-97bdeb84060b' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Trace a build, image, registry, and running container without treating them as interchangeable.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A teammate says “the container is in the registry,” but the operator cannot find it running on the host.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which artifact is stored, and which one is a process?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A Dockerfile describes a build; an image is the resulting layered artifact; a registry stores images; a container is a running or stopped instance created from an image.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Build an image from a reviewed Dockerfile, tag it with a version, push to a trusted registry, then run that exact tag in a test environment.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Put build, tag, push, pull, and run in order. Where would you scan or review an image before release?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Clear names for build artifact and runtime process make release discussions safer.</p></section>';
-- UPDATE public.lessons SET module_id = 'cb995e82-7671-438f-9ead-8e88b3f75284', title = 'What are Containers?', content = 'Containers are lightweight, executable packages that include everything needed to run an application: code, runtime, system tools, libraries, and settings.' WHERE id = 'b30cd886-da8f-4a4e-ae46-ab316110a961' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain what a container packages and what it shares with the host.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>An application depends on a particular runtime and library versions. Recreating those by hand on each server causes inconsistent behavior.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which dependencies belong with the app, and which services remain external?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A container image packages an application and much of its user-space environment. A running container is an isolated process using the host kernel; it is not a complete virtual machine.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A web app image can include its runtime and code while connecting to a managed database through configuration provided at runtime.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Sort runtime, app code, database data, and secret keys into “image,” “external service,” or “runtime configuration.” Explain one reason not to bake credentials into an image.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Containers improve repeatability but do not remove the need for secure configuration and data management.</p></section>';
-- UPDATE public.lessons SET module_id = '5ba9d395-bdcf-4c98-aab4-08612f0a026e', title = 'Linux Networking Fundamentals', content = 'IP addressing, subnetting, routing, DNS, and basic network troubleshooting.' WHERE id = '89f499aa-149b-4ab7-b1b3-8d8b41b3ae1b' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Describe how a client, DNS name, port, and service participate in a network request.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A site works from the server itself but cannot be reached from a browser.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Is the service listening, is the name resolving, and is the intended port reachable?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>DNS maps names to addresses; a port identifies an application endpoint on a host. Firewalls and network routes decide whether traffic can reach it.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Trace browser → DNS → server address → allowed port → web process. A local `curl` success does not prove an external firewall allows the request.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Draw the path for an HTTPS request and list two separate checks for name resolution and service reachability.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Network troubleshooting follows the request path one boundary at a time.</p></section>';
-- UPDATE public.lessons SET module_id = '5ba9d395-bdcf-4c98-aab4-08612f0a026e', title = 'Text Processing and Regular Expressions', content = 'Using sed, awk, and regular expressions for powerful text transformation capabilities.' WHERE id = 'bf50a4ae-4545-465f-93af-730d7e38e341' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Filter structured log lines carefully and explain the limits of a text match.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>After a release, an operator wants to count lines containing a known request ID in a local log.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Would a broad pattern also match similar IDs or unrelated text?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Text tools such as `grep`, `cut`, and `awk` can filter records. Regular expressions describe patterns but do not understand the full structure of a log format.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use `grep -F &quot;request-42&quot; app.log` for an exact fixed string. Restrict access to logs because they may contain personal information or credentials.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Choose a literal search or a regular expression for finding one request ID. What could a plain substring match include by mistake?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A search result is evidence to inspect, not a complete diagnosis. Protect the data being searched.</p></section>';
-- UPDATE public.lessons SET module_id = '5ba9d395-bdcf-4c98-aab4-08612f0a026e', title = 'Shell Scripting with Bash', content = 'Writing scripts that can be executed by the bash shell to perform sequences of commands.' WHERE id = '48eeaa97-66c3-4365-83c0-fe103776e656' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Turn a repeated, safe check into a small script with explicit inputs and failure handling.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A team manually checks three service URLs after every release and sometimes forgets one.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What is the same each time, and what should happen if a check fails?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>A shell script runs commands in sequence. Quoting variables, validating inputs, and stopping on meaningful errors prevents surprising behavior.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>A health-check script can call `curl --fail --silent &quot;$url&quot;` and report success only when the request returns a successful status. Keep target URLs explicit.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Outline a script that checks a local health endpoint and exits nonzero on failure. Include a clear message and avoid secrets in output.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Automation should make repeated work consistent and failures visible.</p></section>';
-- UPDATE public.lessons SET module_id = '5ba9d395-bdcf-4c98-aab4-08612f0a026e', title = 'Essential Linux Commands', content = 'ls, cd, pwd, mkdir, rm, cp, mv, grep, find, chmod, chown, ps, top, df, du, and more.' WHERE id = 'aef0afa9-564c-4d9c-bd30-25f90895c035' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Choose basic file and process commands for a task and understand their effect before execution.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A teammate receives a folder of logs and needs to find the newest file without changing any evidence.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>Which commands inspect data, and which ones change it?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Commands such as `pwd`, `ls`, `cat`, `grep`, and `ps` help inspect location, files, text, and processes. Options and paths matter; destructive commands should be reviewed carefully.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>List logs with `ls -lt`, then inspect one named file with `less app.log`. Avoid recursive deletion or copying sensitive logs to an untrusted location.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>For a read-only incident review, choose commands to identify a log file and search for a request ID. State what each command reads.</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>Know the command’s scope before running it, especially when it can alter or remove files.</p></section>';
-- UPDATE public.lessons SET module_id = '5ba9d395-bdcf-4c98-aab4-08612f0a026e', title = 'Linux Fundamentals', content = 'Linux is a family of open-source Unix-like operating systems based on the Linux kernel.' WHERE id = '61bb99b6-4c81-43e3-bbbf-c9dfe8eeac9a' AND content IS NOT DISTINCT FROM '<section class="lesson-section"><h3>Learning Objective</h3><p>Explain how a Linux process, file, and user fit into the environment an application needs.</p></section>
-- <section class="lesson-section"><h3>Story</h3><p>A developer’s service works on a laptop but fails on a server because its working directory and environment differ.</p></section>
-- <section class="lesson-section"><h3>Discovery</h3><p>What does the process expect to find, and under which user is it running?</p></section>
-- <section class="lesson-section"><h3>Concept</h3><p>Linux exposes files, processes, users, and devices through a consistent filesystem. Permissions determine which users can read, write, or execute a file.</p></section>
-- <section class="lesson-section"><h3>Example</h3><p>Use `pwd`, `ls -la`, and `whoami` to inspect the current directory, visible files, and account before diagnosing a service.</p></section>
-- <section class="lesson-section"><h3>Challenge</h3><p>Write down three facts to inspect before changing a failing service. Why is checking the current user safer than running every command as an administrator?</p></section>
-- <section class="lesson-section"><h3>Takeaway</h3><p>A reliable diagnosis starts by observing the environment and permissions.</p></section>';
-- COMMIT;
